mapper.update:
UPDATE odin_atlas_task_instance_lineage_nodes
SET is_source = #{source}
WHERE guid = #{guid}

mapper.select:
SELECT child_node.`instance_guid` AS `instanceGuid`, parent_instance.`guid` AS `dependentInstanceGuid` FROM `odin_atlas_task_instance_lineage_nodes` AS child_node JOIN `odin_atlas_task_instance_lineage_adjacent` AS instance_edge ON instance_edge.`guid` = child_node.`guid` JOIN `odin_atlas_task_instance_lineage_nodes` AS parent_node ON parent_node.`guid` = instance_edge.`parent_guid` JOIN `hydra_task_instances` AS parent_instance ON parent_instance.`guid` = parent_node.`instance_guid` WHERE child_node.`instance_guid` IN
#{instanceGuid}
AND ( parent_instance.`run_status` IS NULL OR parent_instance.`run_status` != #{finishedStatus} )
